import React, { useMemo } from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadInter = makeLoadFont('Inter');

// Load fonts at module level
const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: interFamily } = loadInter();

// --- SCHEMA DEFINITION ---


export type StatsDashboardProps = Record<string, any>;

// --- HELPER COMPONENTS ---

const Icon = ({
  type,
  color,
  size = 48,
}: {
  type: string;
  color: string;
  size?: number;
}) => {
  const getPath = () => {
    switch (type) {
      case "eye":
        return "M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z";
      case "user":
        return "M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z";
      case "deal": 
        return "M20 6h-4V4c0-1.11-.89-2-2-2h-4c-1.11 0-2 .89-2 2v2H4c-1.11 0-1.99.89-1.99 2L2 19c0 1.11.89 2 2 2h16c1.11 0 2-.89 2-2V8c0-1.11-.89-2-2-2zm-6 0h-4V4h4v2z";
      case "repeat":
        return "M12 4V1L8 5l4 4V6c3.31 0 6 2.69 6 6 0 1.01-.25 1.97-.7 2.8l1.46 1.46C19.54 15.03 20 13.57 20 12c0-4.42-3.58-8-8-8zm0 14c-3.31 0-6-2.69-6-6 0-1.01.25-1.97.7-2.8L5.24 7.74C4.46 8.97 4 10.43 4 12c0 4.42 3.58 8 8 8v3l4-4-4-4v3z";
      case "wallet":
        return "M21 7.28V5c0-1.1-.9-2-2-2H5c-1.11 0-2 .9-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2v-2.28c.59-.35 1-.98 1-1.72V9c0-.74-.41-1.37-1-1.72zM20 9v6h-2V9h2zm-8 10H5V5h14v2h-6c-1.1 0-2 .9-2 2v6c0 1.1.9 2 2 2h6v2z";
      default:
        return "";
    }
  };

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill={color}
      style={{ filter: `drop-shadow(0 0 8px ${color}80)` }}
    >
      <path d={getPath()} />
    </svg>
  );
};

// --- MAIN COMPONENT ---

const StatsDashboard: React.FC<StatsDashboardProps> = ({
  backgroundColor = "#1A0505", // Casino dark red vibe
  transparentBackground = false,
  durationInSeconds = 10,
  accentColor = "#FFD700", // Jackpot gold
  cardBackgroundColor = "#111111",
  mainValue = "10,000",
  mainLabel = "JACKPOT",
  stats = [
    { icon: "eye", label: "VIEWS", value: "2.4M" },
    { icon: "user", label: "SUBS", value: "184K" },
    { icon: "deal", label: "DEALS", value: "27" },
    { icon: "repeat", label: "CLIENTS", value: "92" },
    { icon: "wallet", label: "PAYOUT", value: "$47K" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const jackpotTriggerFrame = 90;
  const isJackpotHit = frame >= jackpotTriggerFrame;

  // Generate deterministic rays that flash intensely during jackpot
  const rays = useMemo(() => {
    return new Array(24).fill(0).map((_, i) => ({
      angle: (360 / 24) * i + random(`ray-${i}`) * 10,
      length: height * 1.5,
      opacity: random(`rayOp-${i}`) * 0.15 + 0.05,
    }));
  }, [height]);

  // Generate a fountain of gold coins for the jackpot explosion
  const coins = useMemo(() => {
    return new Array(250).fill(0).map((_, i) => {
      const seed = i;
      return {
        vx: (random(`vx-${seed}`) - 0.5) * 45, // Spread horizontally
        vy: -random(`vy-${seed}`) * 40 - 25, // Shoot upwards strongly
        rotX: random(`rx-${seed}`) * 360,
        rotY: random(`ry-${seed}`) * 360,
        rotSpeedX: random(`rsx-${seed}`) * 25 - 12,
        rotSpeedY: random(`rsy-${seed}`) * 25 - 12,
        size: random(`size-${seed}`) * 30 + 15,
        color: random(`color-${seed}`) > 0.15 ? accentColor : "#FFFBE6", // mostly gold, some bright highlights
      };
    });
  }, [accentColor]);

  // Main text scrambling logic (locks in digits over time until the jackpot hits)
  const displayMainValue = mainValue.split('').map((char, index) => {
    if (!/[0-9]/.test(char)) return char; // Keep commas, currency symbols static
    const charLockFrame = jackpotTriggerFrame - (mainValue.length - index) * 6;
    if (frame < charLockFrame) {
      return Math.floor(random(`scramble-${frame}-${index}`) * 10).toString();
    }
    return char;
  }).join('');

  // Jackpot main text pop animation
  const jackpotSpring = spring({
    frame: frame - jackpotTriggerFrame,
    fps,
    config: { damping: 12, stiffness: 90 },
  });
  
  // Slight pulsing scale after the initial hit bounce
  const postHitPulse = isJackpotHit 
    ? Math.sin((frame - jackpotTriggerFrame) * 0.1) * 0.05 
    : 0;
    
  const mainTextScale = frame < jackpotTriggerFrame 
    ? 0.9 
    : interpolate(jackpotSpring, [0, 1], [0.9, 1.2]) + postHitPulse;

  // Flash overlay on screen when jackpot hits
  const flashOpacity = isJackpotHit
    ? interpolate(frame - jackpotTriggerFrame, [0, 8, 24], [0, 0.8, 0], { extrapolateRight: "clamp" })
    : 0;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        overflow: "hidden",
      }}
    >
      {/* Background Radial Glow */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: "100%",
          height: "100%",
          background: `radial-gradient(circle at center, ${isJackpotHit ? accentColor + '40' : accentColor + '10'} 0%, transparent 70%)`,
        }}
      />

      {/* Sunburst Rays */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: 0,
          height: 0,
          transform: `rotate(${frame * (isJackpotHit ? 0.3 : 0.05)}deg)`,
        }}
      >
        {rays.map((ray, i) => {
          // Strobe effect during jackpot
          const rayPulse = isJackpotHit ? Math.sin(frame * 0.5 + i) * 0.2 : 0;
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                bottom: 0,
                left: -10, // Center based on width
                width: 20,
                height: ray.length,
                background: `linear-gradient(to top, transparent, ${accentColor}, transparent)`,
                opacity: ray.opacity + rayPulse,
                transformOrigin: "bottom center",
                transform: `rotate(${ray.angle}deg)`,
                filter: "blur(4px)",
              }}
            />
          );
        })}
      </div>

      {/* Cards Row (Slot Reels) */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          gap: 24,
          position: "absolute",
          top: 180,
          left: "50%",
          transform: "translateX(-50%)",
          zIndex: 10,
        }}
      >
        {stats.map((stat, i) => {
          const reelStopFrame = 30 + i * 12; // Each reel stops sequentially before jackpot
          const isSpinning = frame < reelStopFrame;
          
          // Downward motion blur logic for spin
          const itemHeight = 300;
          const spinProgress = (frame * 120) % itemHeight; 
          
          // The bounce when reel locks into place
          const snapSpring = spring({
            frame: frame - reelStopFrame,
            fps,
            config: { damping: 14, stiffness: 120 },
          });
          const snapY = interpolate(snapSpring, [0, 1], [-80, 0]);
          
          const contentY = isSpinning ? spinProgress - itemHeight / 2 : snapY;
          const contentBlur = isSpinning ? 12 : 0;

          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: 220,
                height: 280,
                backgroundColor: cardBackgroundColor,
                borderRadius: 16,
                border: `4px solid ${isJackpotHit ? accentColor : "#444"}`,
                boxShadow: isJackpotHit 
                  ? `0 0 40px ${accentColor}80, inset 0 10px 30px rgba(0,0,0,0.9)` 
                  : `0 20px 40px rgba(0,0,0,0.5), inset 0 10px 30px rgba(0,0,0,0.9)`,
                overflow: "hidden",
              }}
            >
              {/* Inner shadows to simulate physical curved reel window */}
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: `linear-gradient(to bottom, rgba(0,0,0,0.8) 0%, transparent 20%, transparent 80%, rgba(0,0,0,0.8) 100%)`,
                  zIndex: 5,
                  pointerEvents: "none",
                }}
              />

              {/* Reel Content Wrapper */}
              <div
                style={{
                  width: "100%",
                  height: "100%",
                  transform: `translateY(${contentY}px)`,
                  filter: `blur(${contentBlur}px)`,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: "0 20px",
                  position: "relative",
                  zIndex: 2,
                }}
              >
                <div style={{ marginBottom: 20 }}>
                  <Icon type={stat.icon} color={isJackpotHit ? accentColor : "#FFFFFF"} size={60} />
                </div>
                
                <div
                  style={{
                    color: "rgba(255,255,255,0.7)",
                    fontSize: 14,
                    fontWeight: 700,
                    letterSpacing: "0.2em",
                    marginBottom: 12,
                  }}
                >
                  {stat.label}
                </div>
                
                <div
                  style={{
                    color: isJackpotHit ? accentColor : "#FFFFFF",
                    fontFamily: montserratFamily,
                    fontSize: 42,
                    fontWeight: 800,
                  }}
                >
                  {stat.value}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Large Bottom Jackpot Area */}
      <div
        style={{
          position: "absolute",
          bottom: 120,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `scale(${mainTextScale})`,
          zIndex: 15,
        }}
      >
        <div
          style={{
            fontFamily: montserratFamily,
            fontSize: 240,
            fontWeight: 900,
            lineHeight: 1,
            background: `linear-gradient(135deg, #FFF 0%, ${accentColor} 30%, #FF8C00 80%, #FFF 100%)`,
            backgroundSize: "200% 200%",
            backgroundPosition: isJackpotHit ? `${(frame * 2) % 100}% 50%` : "0% 50%",
            WebkitBackgroundClip: "text",
            color: "transparent",
            filter: `drop-shadow(0px 15px 40px ${accentColor}${isJackpotHit ? '90' : '40'})`,
            marginBottom: -10,
            whiteSpace: "nowrap",
          }}
        >
          {displayMainValue}
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 24,
            width: "50%",
            justifyContent: "center",
            opacity: frame < 40 ? interpolate(frame, [10, 40], [0, 1]) : 1,
          }}
        >
          <div
            style={{
              height: 4,
              flexGrow: 1,
              background: `linear-gradient(to left, ${accentColor}, transparent)`,
              boxShadow: `0 0 10px ${accentColor}`,
            }}
          />
          <div
            style={{
              color: isJackpotHit ? "#FFF" : accentColor,
              fontSize: 36,
              fontWeight: 800,
              letterSpacing: "0.4em",
              textShadow: isJackpotHit ? `0 0 20px ${accentColor}` : "none",
            }}
          >
            {mainLabel}
          </div>
          <div
            style={{
              height: 4,
              flexGrow: 1,
              background: `linear-gradient(to right, ${accentColor}, transparent)`,
              boxShadow: `0 0 10px ${accentColor}`,
            }}
          />
        </div>
      </div>

      {/* Coin Fountain Particle System */}
      <div style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 20 }}>
        {isJackpotHit &&
          coins.map((coin, i) => {
            const coinFrame = frame - jackpotTriggerFrame;
            const gravity = 1.8;
            
            // Start from the center bottom (where the jackpot text is)
            const startX = width / 2;
            const startY = height - 150;
            
            const currentX = startX + coin.vx * coinFrame;
            const currentY = startY + coin.vy * coinFrame + 0.5 * gravity * coinFrame * coinFrame;
            
            const currentRotX = coin.rotX + coin.rotSpeedX * coinFrame;
            const currentRotY = coin.rotY + coin.rotSpeedY * coinFrame;

            // Performance: don't render if it falls completely off screen
            if (currentY > height + 100) return null;

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  top: currentY,
                  left: currentX,
                  width: coin.size,
                  height: coin.size,
                  backgroundColor: coin.color,
                  borderRadius: "50%",
                  transform: `translate(-50%, -50%) rotateX(${currentRotX}deg) rotateY(${currentRotY}deg)`,
                  boxShadow: `0 0 15px ${coin.color}60, inset -3px -3px 8px rgba(0,0,0,0.3), inset 3px 3px 8px rgba(255,255,255,0.8)`,
                }}
              />
            );
          })}
      </div>

      {/* Global Jackpot Flash */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundColor: "#FFFFFF",
          opacity: flashOpacity,
          pointerEvents: "none",
          zIndex: 50,
          mixBlendMode: "overlay",
        }}
      />
    </AbsoluteFill>
  );
};

export default StatsDashboard;